{
    if (auto battlePet = _player->GetBattlePet(packet.BattlePetGUID))
    {
        if (battlePet->Flags & packet.Flags)
            battlePet->Flags = battlePet->Flags & ~packet.Flags;
        else
            battlePet->Flags |= packet.Flags;
        battlePet->needSave = true;
    }
