void WorldSession::HandleCageBattlePet(WorldPackets::BattlePet::BattlePetGuidRead& packet)
{
    // ReSharper disable once CppUnreachableCode
    auto const& battlePet = _player->GetBattlePet(packet.BattlePetGUID);
    if (!battlePet)
