            {
                switch (eventId)
                {
                    case EVENT_CHECK_ENERGY:
                        if (me->GetPower(POWER_ENERGY) < 100)
                        {
                            if (!me->HasAura(SPELL_SHADOW_FADE))
                                me->SetPower(POWER_ENERGY, me->GetPower(POWER_ENERGY) + urand(1, 2));
                            events.RescheduleEvent(EVENT_CHECK_ENERGY, 1000);
